#[derive(Debug, PartialEq, Eq, PartialOrd, Ord, Clone)]
pub struct Version {
    pub major: u64,
    pub minor: u64,
    pub patch: u64,
    pub prerelease: Option<String>,
    pub build: Option<String>,
}

pub fn parse(s: &str) -> Result<Version, &'static str> {
    let parts: Vec<&str> = s.splitn(2, '-').collect();
    let main = parts[0];
    let rest = parts.get(1);

    let (main, build) = if let Some(r) = rest {
        let sub_parts: Vec<&str> = r.splitn(2, '+').collect();
        (main, Some(sub_parts))
    } else {
        let sub_parts: Vec<&str> = main.splitn(2, '+').collect();
        if sub_parts.len() > 1 {
            (sub_parts[0], Some(vec!["", sub_parts[1]]))
        } else {
            (main, None)
        }
    };

    let main_parts: Vec<&str> = main.split('.').collect();
    if main_parts.len() != 3 {
        return Err("invalid version");
    }

    let major = main_parts[0].parse().map_err(|_| "invalid major")?;
    let minor = main_parts[1].parse().map_err(|_| "invalid minor")?;
    let patch = main_parts[2].parse().map_err(|_| "invalid patch")?;

    let (prerelease, build) = match build {
        Some(b) => (
            if b[0].is_empty() { None } else { Some(b[0].to_string()) },
            if b.len() > 1 { Some(b[1].to_string()) } else { None },
        ),
        None => (None, None),
    };

    Ok(Version {
        major,
        minor,
        patch,
        prerelease,
        build,
    })
}

pub fn to_string(v: &Version) -> String {
    let mut s = format!("{}.{}.{}", v.major, v.minor, v.patch);
    if let Some(ref p) = v.prerelease {
        s.push('-');
        s.push_str(p);
    }
    if let Some(ref b) = v.build {
        s.push('+');
        s.push_str(b);
    }
    s
}

pub fn compare(a: &Version, b: &Version) -> i8 {
    if a == b {
        0
    } else if a < b {
        -1
    } else {
        1
    }
}

pub fn bump_major(v: &Version) -> Version {
    Version {
        major: v.major + 1,
        minor: 0,
        patch: 0,
        prerelease: None,
        build: None,
    }
}

pub fn bump_minor(v: &Version) -> Version {
    Version {
        major: v.major,
        minor: v.minor + 1,
        patch: 0,
        prerelease: None,
        build: None,
    }
}

pub fn bump_patch(v: &Version) -> Version {
    Version {
        major: v.major,
        minor: v.minor,
        patch: v.patch + 1,
        prerelease: None,
        build: None,
    }
}

