#[derive(Debug, PartialEq, Eq, Clone)]
pub struct Version {
    pub major: u64,
    pub minor: u64,
    pub patch: u64,
    pub prerelease: Option<String>,
    pub build: Option<String>,
}

impl PartialOrd for Version {
    fn partial_cmp(&self, other: &Self) -> Option<std::cmp::Ordering> {
        Some(self.cmp(other))
    }
}

impl Ord for Version {
    fn cmp(&self, other: &Self) -> std::cmp::Ordering {
        self.major
            .cmp(&other.major)
            .then(self.minor.cmp(&other.minor))
            .then(self.patch.cmp(&other.patch))
            .then(match (&self.prerelease, &other.prerelease) {
                (None, None) => std::cmp::Ordering::Equal,
                (None, _) => std::cmp::Ordering::Greater,
                (_, None) => std::cmp::Ordering::Less,
                (Some(a), Some(b)) => a.cmp(b),
            })
    }
}

pub fn parse(s: &str) -> Result<Version, &'static str> {
    let (main, rest) = if let Some(idx) = s.find('-') {
        (&s[..idx], Some(&s[idx + 1..]))
    } else {
        (s, None)
    };

    let (main, build) = if let Some(r) = rest {
        if let Some(idx) = r.find('+') {
            (&main[..], Some((&r[..idx], Some(&r[idx + 1..]))))
        } else {
            (&main[..], Some((r, None)))
        }
    } else {
        if let Some(idx) = main.find('+') {
            (&main[..idx], Some(("", Some(&main[idx + 1..]))))
        } else {
            (main, None)
        }
    };

    let main_parts: Vec<&str> = main.split('.').collect();
    if main_parts.len() != 3 {
        return Err("invalid version");
    }

    let major = main_parts[0].parse().map_err(|_| "invalid major")?;
    let minor = main_parts[1].parse().map_err(|_| "invalid minor")?;
    let patch = main_parts[2].parse().map_err(|_| "invalid patch")?;

    let (prerelease, build) = match build {
        Some((p, b)) => (
            if p.is_empty() { None } else { Some(p.to_string()) },
            b.map(|s| s.to_string()),
        ),
        None => (None, None),
    };

    Ok(Version {
        major,
        minor,
        patch,
        prerelease,
        build,
    })
}

pub fn to_string(v: &Version) -> String {
    let mut s = format!("{}.{}.{}", v.major, v.minor, v.patch);
    if let Some(ref p) = v.prerelease {
        s.push('-');
        s.push_str(p);
    }
    if let Some(ref b) = v.build {
        s.push('+');
        s.push_str(b);
    }
    s
}

pub fn compare(a: &Version, b: &Version) -> i8 {
    match a.cmp(b) {
        std::cmp::Ordering::Less => -1,
        std::cmp::Ordering::Equal => 0,
        std::cmp::Ordering::Greater => 1,
    }
}

pub fn bump_major(v: &Version) -> Version {
    Version {
        major: v.major + 1,
        minor: 0,
        patch: 0,
        prerelease: None,
        build: None,
    }
}

