#[derive(Debug, PartialEq, Eq, Clone)]
pub struct Version {
    pub major: u64,
    pub minor: u64,
    pub patch: u64,
    pub prerelease: Option<String>,
    pub build: Option<String>,
}

fn is_numeric(s: &str) -> bool {
    !s.is_empty() && s.chars().all(|c| c.is_ascii_digit())
}

fn validate_identifier(s: &str, numeric_allowed: bool) -> bool {
    if s.is_empty() {
        return false;
    }
    if numeric_allowed && is_numeric(s) {
        return s == "0" || !s.starts_with('0');
    }
    s.chars().all(|c| c.is_ascii_alphanumeric() || c == '-')
}

pub fn parse(s: &str) -> Result<Version, &'static str> {
    let (main_part, rest) = if let Some(idx) = s.find('-') {
        let (m, r) = s.split_at(idx);
        (m, Some(&r[1..]))
    } else if let Some(idx) = s.find('+') {
        let (m, r) = s.split_at(idx);
        (m, Some(&r[1..]))
    } else {
        (s, None)
    };

    let main_sub: Vec<&str> = main_part.split('.').collect();
    if main_sub.len() != 3 {
        return Err("invalid version");
    }
    for p in &main_sub {
        if p.is_empty() || (p.len() > 1 && p.starts_with('0')) || !p.chars().all(|c| c.is_ascii_digit()) {
            return Err("invalid version");
        }
    }
    let major = main_sub[0].parse().map_err(|_| "invalid")?;
    let minor = main_sub[1].parse().map_err(|_| "invalid")?;
